# 4G only sites: the X2 ENDC endpoint of the NR 03 Termpoint anchor part (5G sites get it in 04 5G_Config);
# no ExternalGNodeBFunction / TermPointToGNB - a 4G only site has no gNBId
KK_LTE_CONFIG_XML_ANCHOR_4G_ONLY = """
<!-- 4G only site: anchor / termpoint part of NR 03 Termpoint (in 04 5G_Config for 5G sites) without ExternalGNodeBFunction / TermPointToGNB (no gNBId) -->
<rpc message-id="Anchor_X2_ENDC_para" xmlns="urn:ietf:params:xml:ns:netconf:base:1.0">
<edit-config xmlns="urn:ietf:params:xml:ns:netconf:base:1.0">
<target>
<running/>
</target>
<config xmlns:xc="urn:ietf:params:xml:ns:netconf:base:1.0">
<ManagedElement>
<managedElementId>{node}</managedElementId>
<Transport>
<transportId>1</transportId>
<SctpEndpoint xc:operation="create">
<sctpEndpointId>X2_ENDC</sctpEndpointId>
<dtlsSctpSecurityMode>DISABLED</dtlsSctpSecurityMode>
<localIpAddress>ManagedElement={node},Transport=1,Router=LTE_NR,InterfaceIPv6=NR,AddressIPv6=X2_ENDC</localIpAddress>
<portNumber>36422</portNumber>
<sctpProfile>ManagedElement={node},Transport=1,SctpProfile=1</sctpProfile>
</SctpEndpoint>
</Transport>
<ENodeBFunction>
<eNodeBFunctionId>1</eNodeBFunctionId>
<upEndcX2IpAddressRef>ManagedElement={node},Transport=1,Router=LTE_NR,InterfaceIPv6=NR,AddressIPv6=X2_ENDC</upEndcX2IpAddressRef>
<sctpEndcX2Ref>ManagedElement={node},Transport=1,SctpEndpoint=X2_ENDC</sctpEndcX2Ref>
</ENodeBFunction>
</ManagedElement>
</config>
</edit-config>
</rpc>
]]>]]>
"""

